      // blob of danger and leave half the room with nothing happening in it.
      if (avoid && Math.hypot(gx - avoid.x, gy - avoid.y) < avoid.minD) continue;
      for (let ai = 0; ai < 16; ai++) {
        const facing = (ai / 16) * Math.PI * 2;
